-- Estoque consignado: transferencia atomica e auditavel.
BEGIN;
DO $p$ BEGIN IF to_regclass('public.produto_variacoes') IS NULL OR to_regclass('public.produto_movimentacoes') IS NULL OR to_regclass('public.user_roles') IS NULL THEN RAISE EXCEPTION 'Produtos ou user_roles ausentes.'; END IF; IF to_regclass('public.estabelecimentos') IS NOT NULL THEN RAISE EXCEPTION 'Consignacao ja existe.'; END IF; END;
$p$;
CREATE TABLE public.estabelecimentos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,nome text NOT NULL CHECK(length(btrim(nome)) BETWEEN 1 AND 200),responsavel text NOT NULL DEFAULT '',whatsapp text NOT NULL DEFAULT '',comissao_percentual numeric(5,2) NOT NULL DEFAULT 0 CHECK(comissao_percentual BETWEEN 0 AND 100),ativo boolean NOT NULL DEFAULT true,criado_em timestamptz NOT NULL DEFAULT now(),atualizado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.estabelecimento_comissoes(estabelecimento_id uuid NOT NULL REFERENCES public.estabelecimentos(id) ON DELETE CASCADE,variacao_id uuid NOT NULL REFERENCES public.produto_variacoes(id) ON DELETE RESTRICT,percentual numeric(5,2) NOT NULL CHECK(percentual BETWEEN 0 AND 100),PRIMARY KEY(estabelecimento_id,variacao_id));
CREATE TABLE public.consignacao_saldos(estabelecimento_id uuid NOT NULL REFERENCES public.estabelecimentos(id) ON DELETE CASCADE,variacao_id uuid NOT NULL REFERENCES public.produto_variacoes(id) ON DELETE RESTRICT,quantidade integer NOT NULL DEFAULT 0 CHECK(quantidade>=0),atualizado_em timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(estabelecimento_id,variacao_id));
CREATE TABLE public.consignacao_movimentacoes(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,estabelecimento_id uuid NOT NULL REFERENCES public.estabelecimentos(id),variacao_id uuid NOT NULL REFERENCES public.produto_variacoes(id),tipo text NOT NULL CHECK(tipo IN('ENVIO','REPOSICAO','DEVOLUCAO','AJUSTE_POSITIVO','AJUSTE_NEGATIVO')),quantidade integer NOT NULL CHECK(quantidade>0),saldo_anterior integer NOT NULL CHECK(saldo_anterior>=0),saldo_resultante integer NOT NULL CHECK(saldo_resultante>=0),observacao text NOT NULL CHECK(length(btrim(observacao)) BETWEEN 1 AND 1000),movimentado_em timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX consignacao_mov_est_data ON public.consignacao_movimentacoes(estabelecimento_id,movimentado_em DESC);
ALTER TABLE public.estabelecimentos ENABLE ROW LEVEL SECURITY; ALTER TABLE public.estabelecimento_comissoes ENABLE ROW LEVEL SECURITY; ALTER TABLE public.consignacao_saldos ENABLE ROW LEVEL SECURITY; ALTER TABLE public.consignacao_movimentacoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY e ON public.estabelecimentos FOR ALL TO authenticated USING(user_id=(SELECT auth.uid()) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=(SELECT auth.uid()) AND r.role='admin')) WITH CHECK(user_id=(SELECT auth.uid()) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=(SELECT auth.uid()) AND r.role='admin'));
CREATE POLICY ec ON public.estabelecimento_comissoes FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.estabelecimentos e WHERE e.id=estabelecimento_id AND e.user_id=(SELECT auth.uid())) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=(SELECT auth.uid()) AND r.role='admin')) WITH CHECK(EXISTS(SELECT 1 FROM public.estabelecimentos e WHERE e.id=estabelecimento_id AND e.user_id=(SELECT auth.uid())) AND EXISTS(SELECT 1 FROM public.produto_variacoes v WHERE v.id=variacao_id AND v.user_id=(SELECT auth.uid())) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=(SELECT auth.uid()) AND r.role='admin'));
CREATE POLICY cs ON public.consignacao_saldos FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.estabelecimentos e WHERE e.id=estabelecimento_id AND e.user_id=(SELECT auth.uid())) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=(SELECT auth.uid()) AND r.role='admin')); CREATE POLICY cm ON public.consignacao_movimentacoes FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=(SELECT auth.uid()) AND r.role='admin'));
REVOKE ALL ON public.estabelecimentos,public.estabelecimento_comissoes,public.consignacao_saldos,public.consignacao_movimentacoes FROM PUBLIC,anon,authenticated; GRANT SELECT,INSERT,UPDATE,DELETE ON public.estabelecimentos,public.estabelecimento_comissoes TO authenticated; GRANT SELECT ON public.consignacao_saldos,public.consignacao_movimentacoes TO authenticated;
CREATE FUNCTION public.movimentar_consignacao(p_id uuid,p_estabelecimento_id uuid,p_variacao_id uuid,p_tipo text,p_quantidade integer,p_observacao text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
DECLARE u uuid:=auth.uid(); b integer; a integer; own integer; old public.consignacao_movimentacoes%ROWTYPE; BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Autenticacao obrigatoria.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u AND r.role='admin') THEN RAISE EXCEPTION 'Permissao de administrador obrigatoria.'; END IF;
 IF p_id IS NULL OR p_tipo NOT IN('ENVIO','REPOSICAO','DEVOLUCAO','AJUSTE_POSITIVO','AJUSTE_NEGATIVO') OR p_quantidade<1 OR p_observacao IS NULL OR length(btrim(p_observacao))=0 THEN RAISE EXCEPTION 'Dados invalidos.'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('rondy:consignacao:'||p_id::text,0)); SELECT * INTO old FROM public.consignacao_movimentacoes WHERE id=p_id;
 IF FOUND THEN IF old.user_id=u AND old.estabelecimento_id=p_estabelecimento_id AND old.variacao_id=p_variacao_id AND old.tipo=p_tipo AND old.quantidade=p_quantidade AND old.observacao=p_observacao THEN RETURN jsonb_build_object('id',p_id,'saldo',old.saldo_resultante,'ja_aplicada',true); END IF; RAISE EXCEPTION 'ID ja utilizado.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.estabelecimentos e WHERE e.id=p_estabelecimento_id AND e.user_id=u AND e.ativo) THEN RAISE EXCEPTION 'Estabelecimento indisponivel.'; END IF;
 SELECT estoque_atual INTO own FROM public.produto_variacoes WHERE id=p_variacao_id AND user_id=u AND NOT arquivado FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Variacao indisponivel.'; END IF;
 INSERT INTO public.consignacao_saldos(estabelecimento_id,variacao_id) VALUES(p_estabelecimento_id,p_variacao_id) ON CONFLICT DO NOTHING; SELECT quantidade INTO b FROM public.consignacao_saldos WHERE estabelecimento_id=p_estabelecimento_id AND variacao_id=p_variacao_id FOR UPDATE;
 IF p_tipo IN('ENVIO','REPOSICAO') THEN IF own<p_quantidade THEN RAISE EXCEPTION 'Estoque proprio insuficiente.'; END IF; UPDATE public.produto_variacoes SET estoque_atual=estoque_atual-p_quantidade WHERE id=p_variacao_id; INSERT INTO public.produto_movimentacoes(id,user_id,variacao_id,tipo,quantidade,saldo_anterior,saldo_resultante,observacao) VALUES(p_id,u,p_variacao_id,'SAIDA',p_quantidade,own,own-p_quantidade,'Consignacao: '||btrim(p_observacao)); a:=b+p_quantidade;
 ELSIF p_tipo='DEVOLUCAO' THEN IF b<p_quantidade THEN RAISE EXCEPTION 'Saldo consignado insuficiente.'; END IF; UPDATE public.produto_variacoes SET estoque_atual=estoque_atual+p_quantidade WHERE id=p_variacao_id; INSERT INTO public.produto_movimentacoes(id,user_id,variacao_id,tipo,quantidade,saldo_anterior,saldo_resultante,observacao) VALUES(p_id,u,p_variacao_id,'ENTRADA',p_quantidade,own,own+p_quantidade,'Devolucao consignacao: '||btrim(p_observacao)); a:=b-p_quantidade;
 ELSIF p_tipo='AJUSTE_POSITIVO' THEN a:=b+p_quantidade; ELSE IF b<p_quantidade THEN RAISE EXCEPTION 'Ajuste deixa saldo negativo.'; END IF; a:=b-p_quantidade; END IF;
 UPDATE public.consignacao_saldos SET quantidade=a,atualizado_em=clock_timestamp() WHERE estabelecimento_id=p_estabelecimento_id AND variacao_id=p_variacao_id; INSERT INTO public.consignacao_movimentacoes(id,user_id,estabelecimento_id,variacao_id,tipo,quantidade,saldo_anterior,saldo_resultante,observacao) VALUES(p_id,u,p_estabelecimento_id,p_variacao_id,p_tipo,p_quantidade,b,a,btrim(p_observacao)); RETURN jsonb_build_object('id',p_id,'saldo',a,'ja_aplicada',false); END;
$f$;
ALTER FUNCTION public.movimentar_consignacao(uuid,uuid,uuid,text,integer,text) OWNER TO postgres; REVOKE ALL ON FUNCTION public.movimentar_consignacao(uuid,uuid,uuid,text,integer,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.movimentar_consignacao(uuid,uuid,uuid,text,integer,text) TO authenticated;
COMMIT;
